-- =============================================================================
-- Object:      dbo.usp_Order_Create
-- Type:        stored procedure
-- Purpose:     Saves a new order with its items and its first status history row in one transaction. When an order
--              with the same ClientOrderId already exists (a retry, or two requests at the same moment), nothing is
--              saved and Created is 0, so the caller returns the existing order. The database assigns OrderNumber.
-- Parameters:  @Id uniqueidentifier - new order id (sequential, generated by the API)
--              @ClientOrderId uniqueidentifier - id generated by the device that took the order
--              @Channel nvarchar(20), @Status nvarchar(20) - as text, e.g. DineIn, New
--              @TableId uniqueidentifier, @WaiterId uniqueidentifier, @CustomerId uniqueidentifier - nullable
--              @Total decimal(10,2) - sum of the item subtotals, computed by the API
--              @Now datetime2 - current time (UTC): CreatedAt, UpdatedAt, and LastStatusChangeAt
--              @ItemsJson nvarchar(max) - [{ Id, ProductId, Quantity, UnitPrice, Subtotal, Size, Drink, Extras, Exclusions }]
--              @HistoryJson nvarchar(max) - [{ Id, FromStatus, ToStatus, ChangedById, CreatedAt }]
-- Returns:     Created bit, OrderNumber int (null when Created is 0)
-- Author:      JulianH2
-- Jira:        ITACR-9
-- =============================================================================
CREATE OR ALTER PROCEDURE dbo.usp_Order_Create
    @Id uniqueidentifier,
    @ClientOrderId uniqueidentifier,
    @Channel nvarchar(20),
    @Status nvarchar(20),
    @TableId uniqueidentifier,
    @WaiterId uniqueidentifier,
    @CustomerId uniqueidentifier,
    @Total decimal(10, 2),
    @Now datetime2,
    @ItemsJson nvarchar(max),
    @HistoryJson nvarchar(max)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Inserted TABLE (OrderNumber int NOT NULL);

    BEGIN TRY
        BEGIN TRANSACTION;

        -- The range lock makes a second request with the same ClientOrderId wait here and then see the first one.
        IF EXISTS (SELECT 1 FROM dbo.Orders WITH (UPDLOCK, HOLDLOCK) WHERE ClientOrderId = @ClientOrderId)
        BEGIN
            ROLLBACK TRANSACTION;
            SELECT CAST(0 AS bit) AS Created, CAST(NULL AS int) AS OrderNumber;
            RETURN;
        END;

        INSERT INTO dbo.Orders (Id, ClientOrderId, Channel, Status, TableId, WaiterId, CustomerId, Total, LastStatusChangeAt, CreatedAt, UpdatedAt)
        OUTPUT inserted.OrderNumber INTO @Inserted (OrderNumber)
        VALUES (@Id, @ClientOrderId, @Channel, @Status, @TableId, @WaiterId, @CustomerId, @Total, @Now, @Now, @Now);

        INSERT INTO dbo.OrderItems (Id, OrderId, ProductId, Quantity, UnitPrice, Subtotal, Size, Drink, Extras, Exclusions, CreatedAt, UpdatedAt)
        SELECT item.Id, @Id, item.ProductId, item.Quantity, item.UnitPrice, item.Subtotal, item.Size, item.Drink,
            COALESCE(item.Extras, N'[]'), COALESCE(item.Exclusions, N'[]'), @Now, @Now
        FROM OPENJSON(@ItemsJson) WITH (
            Id uniqueidentifier,
            ProductId uniqueidentifier,
            Quantity int,
            UnitPrice decimal(10, 2),
            Subtotal decimal(10, 2),
            Size nvarchar(60),
            Drink nvarchar(60),
            Extras nvarchar(max) AS JSON,
            Exclusions nvarchar(max) AS JSON
        ) AS item;

        INSERT INTO dbo.OrderStatusHistory (Id, OrderId, FromStatus, ToStatus, ChangedById, CreatedAt, UpdatedAt)
        SELECT history.Id, @Id, history.FromStatus, history.ToStatus, history.ChangedById, history.CreatedAt, history.CreatedAt
        FROM OPENJSON(@HistoryJson) WITH (
            Id uniqueidentifier,
            FromStatus nvarchar(20),
            ToStatus nvarchar(20),
            ChangedById uniqueidentifier,
            CreatedAt datetime2
        ) AS history;

        COMMIT TRANSACTION;
        SELECT CAST(1 AS bit) AS Created, inserted.OrderNumber FROM @Inserted AS inserted;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
        BEGIN
            ROLLBACK TRANSACTION;
        END;

        -- 2601/2627: the unique index on ClientOrderId rejected a concurrent duplicate that got past the lock.
        IF ERROR_NUMBER() IN (2601, 2627) AND EXISTS (SELECT 1 FROM dbo.Orders WHERE ClientOrderId = @ClientOrderId)
        BEGIN
            SELECT CAST(0 AS bit) AS Created, CAST(NULL AS int) AS OrderNumber;
            RETURN;
        END;

        THROW;
    END CATCH;
END;
